import com.android.tools.lint.detector.api.*
import com.intellij.psi.PsiElementVisitor
import org.jetbrains.uast.*

class PictureInPictureDetector : Detector(), SourceCodeScanner {

    override fun getApplicableConstructorTypes(): List<String> = listOf("android.app.PictureInPictureParams.Builder")

    override fun visitConstructor(
        context: JavaContext,
        node: UCallExpression,
        visitor: PsiElementVisitor
    ) {
        // Only inspect Builder constructions that are immediately chained into a build() call
        val chain = node.findTopLevelChain()
        val calls = chain.collectCalls()
        var hasAutoEnterEnabled = false
        var hasSourceRectHint = false
        for (call in calls) {
            val methodName = call.methodName ?: continue
            when (methodName) {
                "setAutoEnterEnabled" -> {
                    val arg = call.valueArguments.firstOrNull()
                    if (arg is ULiteralExpression && arg.value == true) {
                        hasAutoEnterEnabled = true
                    }
                }
                "setSourceRectHint" -> {
                    if (call.valueArguments.isNotEmpty()) {
                        hasSourceRectHint = true
                    }
                }
            }
        }
        if (!hasAutoEnterEnabled || !hasSourceRectHint) {
            context.report(
                ISSUE,
                node,
                context.getLocation(node),
                "Picture-in-Picture should use setAutoEnterEnabled(true) and setSourceRectHint(...) for smoother transitions on Android 12+"
            )
        }
    }

    private fun UCallExpression.findTopLevelChain(): UExpression {
        var current: UExpression = this
        while (true) {
            val parent = current.uastParent
            if (parent is UQualifiedReferenceExpression && parent.receiver === current) {
                current = parent
            } else {
                break
            }
        }
        return current
    }

    private fun UExpression.collectCalls(): List<UCallExpression> {
        val result = mutableListOf<UCallExpression>()
        var current: UExpression? = this
